INSERT INTO public.source (id, title, source_type, author, edition, url, note)
SELECT id, title, source_type, author, edition, url, note FROM jsonb_populate_recordset(NULL::public.source, '[{"title": "旧五代史·卷112·太祖本纪三·广顺元年十二月", "source_type": "primary", "author": "薛居正等", "edition": "选定TXT逐字导出；电子本，纸本及异文待核。", "url": "https://github.com/greed-216/histree/blob/97a2c54a1eb33b08fa864fe14e9ca184db2402cc/content/books/zizhi-tongjian/vol-290/year-0951/part-10/sources/library/jiuwudaishi-112-december-expedition/source.txt", "note": "《旧五代史》卷112·太祖本纪三·广顺元年十二月，段落 jiu-wudaishi-205deb4a7860-p002668；已核上下文及传主，纸本及异文待核。", "id": "dc4d556d-5461-5f7f-afde-3c4a49643247"}, {"title": "资治通鉴·卷290·广顺元年·十一月至十二月及年末追述", "source_type": "primary", "author": "司马光等", "edition": "选定TXT逐字导出；电子本，纸本及异文待核。", "url": "https://github.com/greed-216/histree/blob/97a2c54a1eb33b08fa864fe14e9ca184db2402cc/content/books/zizhi-tongjian/vol-290/year-0951/part-10/sources/library/tongjian-290-951-year-end/source.txt", "note": "《资治通鉴》卷290·广顺元年·十一月至十二月及年末追述，段落 zizhi-tongjian-a63549944a71-p003448；已核上下文及传主，纸本及异文待核。", "id": "67e73719-49e5-5b82-aaed-c024f28176b0"}, {"title": "资治通鉴·卷290·广顺元年·十月至十一月入楚与晋州战事", "source_type": "primary", "author": "司马光等", "edition": "选定TXT逐字导出；电子本，纸本及异文待核。", "url": "https://github.com/greed-216/histree/blob/b5396b868c179978bf5637eb7c5dc784ba41bd1d/content/books/zizhi-tongjian/vol-290/year-0951/part-09/sources/library/tongjian-290-951-october-november/source.txt", "note": "《资治通鉴》卷290·广顺元年·十月至十一月入楚与晋州战事，段落 zizhi-tongjian-a63549944a71-p003447；已核上下文及传主，纸本及异文待核。", "id": "2eb03298-ebb5-51db-b6b7-6e62af86252d"}, {"title": "新五代史·卷65·南汉世家·贺州陷阱", "source_type": "primary", "author": "欧阳修", "edition": "选定TXT逐字导出；电子本，纸本及异文待核。", "url": "https://github.com/greed-216/histree/blob/b8ce7838037279cfbdd88a95bcd6fb9f26236396/content/books/zizhi-tongjian/vol-288/year-0948/part-09/sources/library/xinwudaishi-065-hezhou-traps/source.txt", "note": "《新五代史》卷65·南汉世家·贺州陷阱，段落 xin-wudaishi-b08f244b9241-p003285；已核上下文及传主，纸本及异文待核。", "id": "47327e81-2499-50f5-a4a8-da4df94cd561"}]'::jsonb)
ON CONFLICT (id) DO NOTHING;

INSERT INTO public.person (id, name, aliases, era, birth_year, death_year, description, biography, status)
SELECT id, name, aliases, era, birth_year, death_year, description, biography, status FROM jsonb_populate_recordset(NULL::public.person, '[{"name": "马殷", "aliases": [], "era": "唐末五代十国", "birth_year": null, "death_year": null, "description": "据《资治通鉴》，907年在“后梁封马殷为楚王”中为受封者。", "biography": null, "status": "draft", "id": "7115610f-10b4-5211-b4a5-d2d089e6db83"}, {"name": "马希隐", "aliases": ["馬希隱"], "era": "五代十国", "birth_year": null, "death_year": null, "description": "马殷的幼子，楚国静江节度副使、知桂州。951年面对南汉来信与吴怀恩军到城下，与许可琼率众逃往全州。生卒年未载。", "biography": null, "status": "draft", "id": "c0e98038-d6ef-5cb5-b3f4-ece41c2e48c2"}, {"name": "刘弘熙", "aliases": ["劉弘熙", "刘洪熙", "劉洪熙"], "era": "五代十国", "birth_year": null, "death_year": null, "description": "本批《资治通鉴》与二十四史所见人物：刘弘熙，获封王爵之子。", "biography": null, "status": "draft", "id": "b67079e8-6ec8-5150-9451-5b3ce7983fec"}, {"name": "吴怀恩", "aliases": ["吳懷恩"], "era": "五代十国", "birth_year": null, "death_year": null, "description": "番禺人，南汉内常侍。刘弘度即位后，他与越王刘弘昌多次劝谏，刘弘度没有听从。具体劝谏年月和生卒年未载。", "biography": null, "status": "draft", "id": "10645068-7e2a-59d2-8714-eb605c240fb1"}, {"name": "马希广", "aliases": ["馬希廣", "德丕"], "era": "五代十国", "birth_year": null, "death_year": null, "description": "本批《资治通鉴》与二十四史所见人物：马希广，武安节度副使，临时领府者。", "biography": null, "status": "draft", "id": "eb8e4d76-8384-56ed-a225-77675cfd8927"}, {"name": "彭彦晖", "aliases": ["彭彥暉"], "era": "五代十国", "birth_year": null, "death_year": null, "description": "楚国指挥使。受马希广派遣驻龙峒防南汉，马希萼在衡山时又任他为桂州都监、在城内外巡检使、判军府事。与许可琼在桂州城中交战，败后逃往衡山。生卒年未载。", "biography": null, "status": "draft", "id": "d2774e6e-ab0c-5543-87aa-772616df9390"}, {"name": "马希萼", "aliases": ["馬希萼"], "era": "五代十国", "birth_year": null, "death_year": null, "description": "马希范的弟弟、马希广的兄长。947年马希范死时，任武平节度使、知永州事，部分将领主张拥立他，但最终马希广继位。生卒年尚未录入。", "biography": null, "status": "draft", "id": "9d5be246-b5ae-553e-b5c5-a6a875b2c1cd"}, {"name": "许可琼", "aliases": ["許可瓊"], "era": "五代十国", "birth_year": null, "death_year": null, "description": "许德勋的儿子，楚国水军指挥使。950年受马希广命率五百艘战舰屯城北津，水军接连南津，由马希崇监军。生卒年未载。", "biography": null, "status": "draft", "id": "31ee592e-a1c4-52e7-8bf7-298a4985dab9"}, {"name": "潘玄珪", "aliases": [], "era": "五代十国", "birth_year": null, "death_year": null, "description": "马希隐的支使。951年马希隐与僚佐商议向南汉投降时，他反对投降。生卒年未载。", "biography": null, "status": "draft", "id": "2435d3b5-c307-5f8d-896d-cfee9398ed01"}, {"name": "边镐", "aliases": ["邊鎬"], "era": "五代十国", "birth_year": null, "death_year": null, "description": "金陵人，南唐通事舍人。943年十月任讨张遇贤军监军，用白昌裕为谋主，接连获胜；白昌裕建议开道绕到营后袭击，张遇贤随后逃走被捕。生卒年尚未核。", "biography": null, "status": "draft", "id": "8bcc0004-3382-5f6c-af6e-73ccf4cdd725"}, {"name": "李承戬", "aliases": ["李承戩"], "era": "五代十国", "birth_year": null, "death_year": null, "description": "南唐先锋指挥使。951年十一月奉边镐之命率兵到衡山，催促马希萼入朝。生卒年未载。", "biography": null, "status": "draft", "id": "b30d0817-4d1c-5fc9-a3bb-9a14e3c74102"}, {"name": "王峻", "aliases": [], "era": "五代十国", "birth_year": null, "death_year": null, "description": "安阳人，刘知远的客将。947年奉三表赴契丹，报告贺入大梁、暂不离太原及贡路受阻。《旧五代史》称牙将王峻，记二月出使和携杖回太原。生卒年本段未核。", "biography": null, "status": "draft", "id": "196d9879-50e7-5ff5-9d99-4879fa1ea3a2"}, {"name": "郭威", "aliases": [], "era": "五代十国", "birth_year": null, "death_year": null, "description": "《资治通鉴》卷272同光元年条所见人物：郭威。", "biography": null, "status": "draft", "id": "3fe84db3-aa25-5be9-9dd3-8b46e28213af"}, {"name": "慕容彦超", "aliases": ["慕容彥超"], "era": "五代十国", "birth_year": null, "death_year": null, "description": "后晋濮州刺史，原属吐谷浑，与刘知远同母。945年正月随皇甫遇侦察契丹军，在榆林店受围，与皇甫遇共同救回杜知敏，得到安审琦援军后返回相州。出生及死亡年本段未载。", "biography": null, "status": "draft", "id": "e0c11a24-a441-5d69-b8e3-b5bdc109357b"}, {"name": "郑好谦", "aliases": ["鄭好謙"], "era": "五代十国", "birth_year": null, "death_year": null, "description": "后周通事舍人。951年奉郭威之命前往安抚慕容彦超，并与其盟誓。生卒年未载。", "biography": null, "status": "draft", "id": "0b4ce788-095c-5411-b480-a87a1b41c0ae"}, {"name": "郑麟", "aliases": ["鄭麟"], "era": "五代十国", "birth_year": null, "death_year": null, "description": "慕容彦超的都押牙。951年多次受派入后周朝廷，表面表示诚意，史书记载实际上为侦察朝廷情况。生卒年未载。", "biography": null, "status": "draft", "id": "5caba4fe-d1e6-5a53-8cd2-1960c5422377"}, {"name": "高行周", "aliases": [], "era": "五代十国", "birth_year": null, "death_year": null, "description": "《资治通鉴》卷268乾化三年条所见人物：高行周。", "biography": null, "status": "draft", "id": "659c5f83-09bc-5282-8f02-4c7fa0a62729"}, {"name": "张凝", "aliases": ["張凝"], "era": "五代十国", "birth_year": null, "death_year": null, "description": "后周阁门使。951年十二月奉郭威之命率兵到郓州巡检，以防备慕容彦超。生卒年未载。", "biography": null, "status": "draft", "id": "ad0d7bc5-f6cc-5321-9e2a-93f97ff1fec6"}]'::jsonb)
ON CONFLICT (id) DO NOTHING;

INSERT INTO public.event (id, title, start_year, end_year, time_original, dynasty, description, phases, location_name, location_modern_name, location_lat, location_lng, location_precision, location_note, status)
SELECT id, title, start_year, end_year, time_original, dynasty, description, phases, location_name, location_modern_name, location_lat, location_lng, location_precision, location_note, status FROM jsonb_populate_recordset(NULL::public.event, '[{"title": "刘晟任吴怀恩为西北招讨使，屯兵边境等待进取时机", "start_year": null, "end_year": null, "time_original": "马希广与马希萼争国期间的追述，具体任命与屯兵年份未载", "dynasty": "五代十国", "description": "刘晟任吴怀恩为西北招讨使，屯兵边境等待进取时机。", "phases": [], "location_name": "南汉、楚国边境", "location_modern_name": null, "location_lat": null, "location_lng": null, "location_precision": "unknown", "location_note": "采用史书记载的地点名称，地理坐标尚未核实。", "status": "draft", "id": "1c9b894b-cd43-5c6c-a61e-6922c9cafa95"}, {"title": "马希广派彭彦晖率兵驻龙峒，防备南汉", "start_year": null, "end_year": null, "time_original": "马希广在位、争国期间的追述，具体派兵年份未载", "dynasty": "五代十国", "description": "马希广派彭彦晖率兵驻龙峒，防备南汉。", "phases": [], "location_name": "龙峒", "location_modern_name": null, "location_lat": null, "location_lng": null, "location_precision": "unknown", "location_note": "采用史书记载的地点名称，地理坐标尚未核实。", "status": "draft", "id": "5ac7a64a-7727-5673-9ffd-37f714c1e67b"}, {"title": "马希萼在衡山任彭彦晖掌桂州军务", "start_year": 951, "end_year": 951, "time_original": "951年衡山立府后至十一月桂州失守以前，具体任命日未载", "dynasty": "五代十国", "description": "马希萼在衡山任彭彦晖掌桂州军务。", "phases": [], "location_name": "衡山至桂州", "location_modern_name": null, "location_lat": null, "location_lng": null, "location_precision": "unknown", "location_note": "采用史书记载的地点名称，地理坐标尚未核实。", "status": "draft", "id": "e244bf74-94ab-52e5-a113-ec8a9048c7bd"}, {"title": "马希隐反感彭彦晖获任，秘密通知许可琼", "start_year": 951, "end_year": 951, "time_original": "951年彭彦晖获任桂州军务以后", "dynasty": "五代十国", "description": "马希隐反感彭彦晖获任，秘密通知许可琼。", "phases": [], "location_name": "桂州至蒙州", "location_modern_name": null, "location_lat": null, "location_lng": null, "location_precision": "unknown", "location_note": "采用史书记载的地点名称，地理坐标尚未核实。", "status": "draft", "id": "4066402a-b9cb-5980-be60-e6b2f8c911f9"}, {"title": "许可琼惧怕南汉进逼，放弃蒙州，率兵赴桂州", "start_year": 951, "end